import { Drawer, type DrawerCloseDetail } from '@absoluteui/components/drawer';

const editor = Drawer.create({
  title: 'Edit customer',
  description: 'Changes are saved when you select Save.',
  size: 'lg',
  actions: [
    { label: 'Cancel', value: 'cancel' },
    { label: 'Save', value: 'save', variant: 'primary' },
  ],
});
editor.element.addEventListener('aui-close', (event) => {
  const { returnValue } = (event as CustomEvent<DrawerCloseDetail>).detail;
  if (returnValue === 'save') {
    // persist changes
  }
});
editor.open();

import { Drawer } from '@absoluteui/components/drawer';

const filters = Drawer.create({ title: 'Filters', modal: false, placement: 'start', size: 'sm' });
const list = document.createElement('fieldset');
filters.body.append(list);
document.querySelector('#toggle-filters')?.addEventListener('click', () => {
  if (filters.isOpen) filters.close();
  else filters.open();
});

import { Drawer } from '@absoluteui/components/drawer';

let dirty = true;
const panel = Drawer.create({ title: 'Edit profile', placement: 'bottom' });
panel.element.addEventListener('aui-cancel', (event) => {
  if (dirty) event.preventDefault();
});
panel.open();
dirty = false;
